import spidev
import time
import threading
import paho.mqtt.client as mqtt

class LoadCellReader:
    def __init__(self):
        self.spi = spidev.SpiDev()
        self.spi.open(0, 0)  # Open SPI device at address 0, chip select 0
        self.spi.max_speed_hz = 50000
        self.spi.bits_per_word = 8

    def send_spi_command(self, data):
        try:
            self.spi.xfer2(data)
            return self.spi.readbytes(2)
        except OSError as e:
            print(f"Error during SPI transfer: {e}")
            return None

    def extract_10bit(self, response):
        if response is None:
            return None
        return ((response[1] & 0x03) << 8) | response[2]

    def read_raw_data(self):
        command = [0x01, 0x80, 0x00]
        response = self.send_spi_command(command)
        if response is not None:
            return self.extract_10bit(response)

    def convert_to_weight(self, raw_data):
        try:
            weight = float(raw_data) * (5.0 / 1023.0)
            return round(weight, 2)
        except (ValueError, TypeError):
            print("Error converting raw data to weight.")
            return None

    def close(self):
        self.spi.close()

def mqtt_callback(client, userdata, msg):
    print(f"Received message: {msg.payload.decode()}")

def main():
    reader = LoadCellReader()
    try:
        while True:
            raw_data = reader.read_raw_data()
            if raw_data is not None:
                weight = reader.convert_to_weight(raw_data)
                if weight is not None:
                    print(f"Weight: {weight} kg")
            time.sleep(0.5)

    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
        reader.close()

    except Exception as e:
        print(f"Fatal error: {e}")
        reader.close()

if __name__ == "__main__":
    mqtt_client = mqtt.Client()
    mqtt_client.on_message = mqtt_callback
    mqtt_client.connect("mqtt.server.com", 1883, 60)  # Replace with your MQTT broker
    mqtt_client.loop_forever()

    # Install SIGTERM handler for clean shutdown
    import signal
    signal.signal(signal.SIGTERM, lambda signum, frame: print("\nProgram terminated by system. Cleaning up resources..."))

    main()

