import smbus2
import time
import logging
from contextlib import suppress

logging.basicConfig(level=logging.INFO)

class ADS1015:
    def __init__(self, address=0x48, busnum=1, debug=False):
        self.bus = smbus2.SMBus(busnum)
        self.address = address
        self.debug = debug

        try:
            self.read_config_register()
        except smbus2.SMBusException:
            if debug:
                logging.error("ADS1015 not found on I2C bus.")
            raise

    def read_config_register(self):
        try:
            config_reg = self.bus.read_word_data(self.address, 0x00)
            if config_reg & 0x02:  # Check for device present
                logging.info("ADS1015 found.")
            else:
                if self.debug:
                    logging.error("ADS1015 not found.")
                raise ValueError("ADS1015 not found.")
        except smbus2.SMBusException as e:
            logging.error(f"I2C bus error: {e}")
            raise

    def read_adc_single_ended(self, channel=0, pga=6144, sps=250):
        try:
            adc_config = 0x40 | (channel << 1) | (pga & 0x3FFF) | (sps >> 8)
            self.bus.write_byte_data(self.address, adc_config, 1)
            time.sleep(0.001)  # Wait for conversion to complete
            adc_result = self.bus.read_word_data(self.address, 0x28)
            return adc_result >> 8  # Convert to integer
        except smbus2.SMBusException as e:
            logging.error(f"I2C bus error: {e}")
            return None

    def start_continuous_conversion(self, channel=0, pga=6144, sps=250):
        try:
            adc_config = 0x40 | (channel << 1) | (pga & 0x3FFF) | (sps >> 8)
            self.bus.write_byte_data(self.address, adc_config, 1)
            logging.info("Continuous conversion started.")
        except smbus2.SMBusException as e:
            logging.error(f"I2C bus error: {e}")

    def get_last_conversion_results(self):
        try:
            adc_result = self.bus.read_word_data(self.address, 0x28)
            return adc_result >> 8  # Convert to integer
        except smbus2.SMBusException as e:
            logging.error(f"I2C bus error: {e}")
            return None

    def start_single_ended_comparator(self, channel=0, threshold_high=2047, threshold_low=0, pga=6144, sps=250, active_low=True, traditional_mode=True, latching=False, num_readings=1):
        try:
            adc_config = 0x40 | (channel << 1) | (pga & 0x3FFF) | (sps >> 8)
            self.bus.write_byte_data(self.address, adc_config, 1)

            if active_low:
                self.bus.write_byte_data(self.address, 0x00, 0x01)  # Active low mode

            if traditional_mode:
                self.bus.write_byte_data(self.address, 0x01, 0x00)  # Traditional mode

            if latching:
                self.bus.write_byte_data(self.address, 0x02, 0x01)  # Latching mode

            for _ in range(num_readings):
                self.bus.read_word_data(self.address, 0x2C)  # Read comparator results
                time.sleep(0.001)  # Wait for conversion to complete

            logging.info("Comparator started.")
        except smbus2.SMBusException as e:
            logging.error(f"I2C bus error: {e}")

# Example usage
if __name__ == "__main__":
    try:
        adc = ADS1015()
        adc.start_continuous_conversion()
        time.sleep(5)  # Run for 5 seconds
        print(f"Last conversion result: {adc.get_last_conversion_results()}")
        adc.start_single_ended_comparator(channel=0, threshold_high=1023, threshold_low=511, active_low=True, num_readings=3)
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        adc.bus.close()

