class MotionSensor:
    def __init__(self, sampling_period=SAMPLING_PERIOD, threshold=THRESHOLD):
        self.sampling_period = sampling_period
        self.threshold = threshold
        self.motion_count = 0
        self.start_time = time.time()

    def count_rising_edges(self, pin, bouncetime):
        def callback(channel):
            nonlocal self.motion_count
            if channel == pin:
                self.motion_count += 1
                if time.time() - self.start_time > self.sampling_period:
                    self.start_time = time.time()
                if self.motion_count >= self.threshold:
                    self.motion_detected()
                    self.motion_count = 0
        GPIO.add_event_detect(pin, GPIO.RISING, bouncetime, callback=callback)

    def motion_detected(self):
        logging.info("Motion detected!")
        self.reset_counter()

    def reset_counter(self):
