import smbus2
import time

class ADS1x15:
    def __init__(self, i2c_bus=1):
        self.i2c = smbus2.SMBus(i2c_bus)
        self.address = 0x48
        self.channel = 0
        self.gain = 6144  # Default gain in 1mV steps

    def set_channel(self, channel):
        if not isinstance(channel, int) or channel < 0 or channel > 3:
            raise ValueError("Invalid channel number. Must be between 0 and 3.")
        self.channel = channel

    def set_gain(self, gain):
        if not isinstance(gain, int) or gain < 6144 or gain % 1024 != 0:
            raise ValueError("Invalid gain. Must be a multiple of 1024 between 6144 and 65536.")
        self.gain = gain

    def read_voltage(self, channel=0, gain=6144):
        if not isinstance(channel, int) or channel < 0 or channel > 3:
            raise ValueError("Invalid channel number. Must be between 0 and 3.")
        if not isinstance(gain, int) or gain < 6144 or gain % 1024 != 0:
            raise ValueError("Invalid gain. Must be a multiple of 1024 between 6144 and 65536.")

        try:
            self.i2c.write_byte_data(self.address, 0x40, gain >> 9)  # Set gain
            self.i2c.write_byte_data(self.address, 0x48, channel)  # Set channel
            time.sleep(0.01)  # Wait for ADC to settle
            self.i2c.read_word_data(self.address, 0x44)  # Read raw ADC value
        except smbus2.SMBusException as e:
            print(f"I2C communication error: {e}")
            raise

        raw_value = self.i2c.read_word_data(self.address, 0x44)
        scaled_value = (raw_value * self.gain / 32768.0) * 1024  # Convert to mV
        return scaled_value

# Example usage:
try:
    adc = ADS1x15()
    print(adc.read_voltage(channel=0, gain=6144))  # Read from channel 0 with 6144 gain
    print(adc.read_voltage(channel=1, gain=2048))  # Read from channel 1 with 2048 gain
finally:
    adc.i2c.close()  # Release I2C bus handle on object destruction

