@app.route('/video_feed')
def video_feed():
    def generate():
        while True:
            jpeg_bytes = Camera().get_frame()
            if jpeg_bytes:
                yield (b'--frame\r\n'
                       b'Content-Type: image/jpeg\r\n\r\n' + jpeg_bytes + b'\r\n\r\n')
            else:
                yield [b'--frame\r\n']

    return Response(generate(), mimetype='multipart/x-mixed-replace; boundary=frame')

@app.route('/check_for_objects', methods=['GET'])
def check_for_objects():
    try:
        if config.classifier_name == 'motion_detector':
            detected, _ = Camera().get_object_with_basic_motion_detection()
        else:
            detected, _ = Camera().get_object(config.classifier_name)

        if config.send_email_notifications and detected:
            mail_config.send_email(Camera().get_frame(), config)
            time.sleep(config.email_send_interval)

    except Exception as e:
        print(f"Error checking for objects: {e}")

def check_for_objects_thread():
    while not camera_thread.is_alive():
        Camera().check_for_objects()
        time.sleep(0.1)

def start_camera_thread():
    global camera
    camera = PiCamera(resolution=(640, 480), flip=Flip.FLIP_VERTICAL)
    camera.start_preview()
    camera_thread = threading.Thread(target=check_for_objects_thread)
    camera_thread.start()

def stop_camera_thread():
    camera_thread.join()
    camera.stop_preview()
    camera.close()

def signal_handler(sig, frame):
    print('You pressed Ctrl+C!')
    Camera().stop_camera_thread()
    exit(0)

if __name__ == '__main__':
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    app.run(debug=True, host='0.0.0.0')

    try:
        start_camera_thread()
    except Exception as e:
        print(f"Failed to start camera: {e}")
        exit(1)
