import logging
import gpiozero
from picamera2 import PiCamera
from adafruit_circuitpython_display import Display
from paho.mqtt import client as mqttClient

# Configure logging
logging.basicConfig(filename='water_level.log', level=logging.INFO,
                    format='%(asctime)s - %(levelname)s - %(message)s')

# Default configuration
DEFAULT_CONFIG = {
    "sensor_config": [
        {"trigger_pin": 17, "echo_pin": 18, "offset": 0.0, "max_distance": 200.0},
        {"trigger_pin": 22, "echo_pin": 23, "offset": 0.0, "max_distance": 200.0},
        {"trigger_pin": 24, "echo_pin": 25, "offset": 0.0, "max_distance": 200.0}
    ],
    "global": {
        "alert_threshold_low": 10.0,
        "alert_threshold_high": 180.0,
        "alert_repeat_delay": 60,
        "log_file": "water_level.log"
    }
}

# Load configuration
def load_config(config_file="config.json"):
    if not os.path.exists(config_file):
        logging.info("Config file not found, using defaults.")
        return DEFAULT_CONFIG
    try:
        with open(config_file, 'r') as f:
            return json.load(f)
    except json.JSONDecodeError:
        logging.error("Invalid JSON format in config file.")
        return DEFAULT_CONFIG

# Initialize GPIO
def init_gpio():
    try:
        gpio = gpiozero.GPIO(0)
        for sensor in DEFAULT_CONFIG["sensor_config"]:
            gpio.setup(sensor["trigger_pin"], gpiozero.OUT)
            gpio.setup(sensor["echo_pin"], gpiozero.IN, pull_up_down=gpiozero.PULL_UP)
        return gpio
    except Exception as e:
        logging.error(f"GPIO initialization failed: {e}")
        return None

# Measure distance
def measure_distance(trigger_pin, echo_pin, offset, max_distance):
    gpio.output(trigger_pin, True)
    time.sleep(0.00001)
    gpio.output(trigger_pin, False)
    start_time = time.time()
    while gpio.input(echo_pin) == 0:
        time.sleep(0.0005)
    end_time = time.time()
    pulse_duration = end_time - start_time
    distance = (pulse_duration * 34300) / 2
    water_level = max_distance - distance
    return water_level

# Main loop
def main_loop(gpio, config):
    valid_readings = []
    alert_status = {"low": False, "high": False}
    last_alert_time = time.time()

    while True:
        try:
            readings = []
            for sensor in config["sensor_config"]:
                water_level = measure_distance(sensor["trigger_pin"], sensor["echo_pin"], sensor["offset"], sensor["max_distance"])
                if water_level is not None:
                    readings.append(water_level)

            if len(readings) > 0:
                avg_reading = sum(readings) / len(readings)
                if avg_reading < config["global"]["alert_threshold_low"]:
                    alert_status["low"] = True
                elif avg_reading > config["global"]["alert_threshold_high"]:
                    alert_status["high"] = True

                if alert_status["low"] and time.time() - last_alert_time < config["global"]["alert_repeat_delay"]:
                    logging.warning("Repeated low alert, suppressing.")
                elif alert_status["high"] and time.time() - last_alert_time < config["global"]["alert_repeat_delay"]:
                    logging.warning("Repeated high alert, suppressing.")

                last_alert_time = time.time()

            if len(readings) >= 3:
                median_reading = sorted(readings)[len(readings) // 2]
                valid_readings.append(median_reading)

            if len(valid_readings) == 3:
                logging.info(f"Water level: {median_reading:.2f} cm")

            if len(valid_readings) > 3:
                logging.info(f"Average water level: {sum(valid_readings) / len(valid_readings):.2f} cm")

            if len(valid_readings) > 0:
                logging.info(f"Valid readings: {valid_readings}")

        except Exception as e:
            logging.error(f"Error in main loop: {e}")

        time.sleep(5)

# MQTT setup
def on_connect(client, userdata, flags, rc):
    logging.info("Connected to MQTT broker")

def on_message(client, userdata, msg):
    logging.info(f"Received message: {msg.payload.decode()}")

mqtt_client = mqttClient()
mqtt_client.on_connect = on_connect
mqtt_client.on_message = on_message
mqtt_client.connect("mqtt.example.com", 1883, 60)
mqtt_client.subscribe("water_level/updates")

# Start the application
if __name__ == "__main__":
    gpio = init_gpio()
    config = load_config()
    if gpio is not None:
        main_loop(gpio, config)
    else:
        logging.error("Failed to initialize GPIO, exiting.")

