class BluetoothSerial:
    def __init__(self, port='/dev/rfcomm4', baudrate=38400, timeout=1):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.serial_port = None
        self.logging.info(f"Initializing BluetoothSerial on port {port} at {baudrate} baud")

    def __enter__(self):
        try:
            self.serial_port = serial.Serial(self.port, self.baudrate, timeout=self.timeout)
            self.logging.info(f"BluetoothSerial on {self.port} initialized successfully")
            return self.serial_port
        except serial.SerialException as e:
            self.logging.error(f"Failed to open serial port: {e}")
            raise

    def __exit__(self, exc_type, exc_val, exc_tb):
        if self.serial_port:
            try:
                self.serial_port.close()
                self.logging.info("BluetoothSerial port closed successfully")
            except Exception as e:
                self.logging.error(f"Failed to close serial port: {e}")

    def transmit(self, data):
        try:
            self.serial_port.write(data.encode('utf-8'))
            self.logging.info(f"Transmitted: {len(data.encode('utf-8'))} bytes")
        except serial.SerialException as e:
            self.logging.error(f"Error during transmission: {e}")

    def run(self):
        try:
            while True:
                user_input = input("Enter text (or 'q' to quit): ")
                if user_input.lower() == 'q':
                    break
                prepended_data = f"X{user_input}"
                self.transmit(prepended_data)
        except KeyboardInterrupt:
            self.run()  # Re-enter the loop on Ctrl+C

if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
    with BluetoothSerial() as serial_port:
        serial_port.run()

