import os
import time
import threading
import logging
from PIL import Image, ImageOps, ImageSequence
import picamera2
from gpiozero import OLEDDisplay
from adafruit_circuitpython_ssd1306 import SSD1306_I2C
import paho.mqtt.client as mqtt

class Frame:
    def __init__(self, image):
        self.image = image

class AnimatedGif:
    def __init__(self, display, folder='.'):
        self.display = display
        self.folder = folder
        self.current_file = None
        self.frames = []
        self.is_running = False
        self.thread = None

    def display(self, img):
        self.display.image(img)

    def width(self):
        return self.display.width

    def height(self):
        return self.display.height

    def load_files(self):
        for filename in os.listdir(self.folder):
            if filename.lower().endswith(('.gif', '.GIF')):
                filepath = os.path.join(self.folder, filename)
                try:
                    with Image.open(filepath) as img:
                        if img.is_animated:
                            self.current_file = filename
                            self.preload()
                except Exception as e:
                    logging.warning(f"Invalid GIF file: {filepath}, Error: {str(e)}")

    def preload(self):
        if not self.current_file:
            return

        with Image.open(self.current_file) as img:
            duration = img.info.get('duration')
            loop = img.info.get('loop')

            self.frames = []
            for i in range(img.n_frames):
                frame = img.copy()
                frame.load()
                frame = frame.crop((0, 0, self.display.width, self.display.height))
                frame = ImageOps.pad(frame, (self.display.width, self.display.height), 'black')
                frame = frame.convert('RGB')
                self.frames.append(Frame(frame))

            if duration:
                self.loop_count = int(loop) if loop else float('inf')
            else:
                self.loop_count = 0

    def play(self):
        if not self.frames:
            return False

        if not self.is_running:
            self.is_running = True
            self.thread = threading.Thread(target=self._play)
            self.thread.start()
            return True

        self.thread.join()
        return False

    def _play(self):
        start_time = time.monotonic()
        while self.loop_count > 0:
            if not self.frames:
                break

            frame = self.frames.pop(0)
            elapsed = time.monotonic() - start_time
            if elapsed < frame.duration / 1000:
                time.sleep(frame.duration / 1000 - elapsed)

            self.display.image(frame.image)
            self.display.show()
            self.display.flip()

            if self.loop_count > 0:
                self.loop_count -= 1
            else:
                self.current_file = None
                self.preload()
                break

    def run(self):
        self.is_running = True
        self.thread = threading.Thread(target=self._run)
        self.thread.start()

    def _run(self):
        while self.is_running:
            if self.play():
                time.sleep(0.1)  # Small delay to prevent CPU overload

    def stop(self):
        self.is_running = False
        self.thread.join()

# Setup SSD1306 OLED display
display = SSD1306_I2C(128_64, 64)

# Initialize logging
logging.basicConfig(level=logging.INFO)

# Create AnimatedGif instance
animated_gif = AnimatedGif(display)

# Load and play GIFs from a folder
animated_gif.load_files()
animated_gif.run()

import time
import logging
import subprocess
import threading
from gpiozero import InputDevice
from datetime import datetime

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

def simulate_light_level(device):
    if device.value < 600 or device.value > 1000:
        raise ValueError("Light level out of range")
    return device.value

def simulate_temperature(device):
    if device.value < 20 or device.value > 30:
        raise ValueError("Temperature out of range")
    return device.value

def simulate_voltage_current(device):
    if device.value < 10.0 or device.value > 12.5:
        raise ValueError("Voltage/Current out of range")
    return device.value

def read_pi_temperature():
    try:
        result = subprocess.run(['vcgencmd', 'measure_temp'], capture_output=True, text=True, check=True, timeout=5)
        temp_str = result.stdout.strip()
        temp_c = float(temp_str.split('=')[1].strip('\''))
        return temp_c
    except subprocess.CalledProcessError as e:
        logging.warning(f"Error reading Pi temperature: {e}")
        return None

def log_sensor_data(light, temp, volt, curr, pi_temp):
    try:
        logging.info(f"{datetime.now()} - Light: {light} lux, Temperature: {temp}°C, Voltage: {volt}V, Current: {curr}A, Pi Temperature: {pi_temp}°C")
    except Exception as e:
        logging.error(f"Error logging sensor data: {e}")

def setup_gpio():
    try:
        light_device = InputDevice(17, pull_up=False)
        temp_device = InputDevice(4, pull_up=False)
        volt_curr_device = InputDevice(27, pull_up=False)  # Assuming voltage and current are on another GPIO

        log_sensor_data(simulate_light_level(light_device), simulate_temperature(temp_device), simulate_voltage_current(volt_curr_device), 11.5, read_pi_temperature())
    except Exception as e:
        logging.error(f"Error setting up GPIO: {e}")

def main():
    setup_gpio()
    try:
        while True:
