import smbus2
import time
import logging
import paho.mqtt.client as mqtt

logging.basicConfig(level=logging.INFO)

class DHT20Sensor:
    def __init__(self):
        self.bus = None
        self.address = 0x38
        self.crc_error = False

    def __enter__(self):
        try:
            self.bus = smbus2.SMBus(1)
        except smbus2.SMBusError as e:
            logging.error(f"Failed to open I2C bus: {e}")
            self.bus = None
            raise

    def __exit__(self, exc_type, exc_val, exc_tb):
        if self.bus:
            self.bus.close()
            self.bus = None

    def measure(self):
        if not self.bus:
            return None, None, True

        try:
            self.bus.write_i2c_block_data(self.address, 0x60, [0x33, 0x00])
            status_register = self.bus.read_i2c_block_data(self.address, 0x71)

            start_time = time.time()
            while time.time() - start_time < 0.1:
                current_status = self.bus.read_i2c_block_data(self.address, 0x71)
                if not current_status[7] & 0x80:
                    break

            data = current_status[1:8]
            crc = 0xFF
            for i in range(6):
                crc = (crc << 1) ^ data[i]
                if crc & 0x80:
                    crc_error = True
                    break

            temperature_raw = (data[1] << 8) | data[2]
            humidity_raw = (data[3] << 8) | data[4]

            temperature = (float(temperature_raw) / 5242.88 - 50.0)
            humidity = (float(humidity_raw) / 0x100000) * 100.0

            return temperature, humidity, self.crc_error

        except Exception as e:
            logging.error(f"Error during measurement: {e}")
            return None, None, True

