import smbus2
import time
import logging
import paho.mqtt.client as mqtt

class DHT20:
    def __init__(self):
        self.bus = smbus2.SMBus(1)
        self.address = 0x38
        self.status_register = 0x71
        self.measurement_register = 0xAC
        self.idle_register = 0x71
        self.retries = 0
        self.max_retries = 10
        self.timeout = 0.8
        self.retry_interval = 0.01
        self.previous_result = None
        self.mqtt_client = mqtt.Client()
        self.mqtt_client.on_connect = self.on_connect
        self.mqtt_client.on_message = self.on_message

    def begin(self):
        try:
            self.bus.open_bus()
            time.sleep(0.5)
            status = self.bus.read_i2c_block_data(self.address, self.status_register, 2)
            if status[0] & 0x18 != 0x18:
                logging.error("DHT20 status register 0x71 does not match expected value 0x18")
                return False
            return True
        except OSError as e:
            logging.warning(f"I2C read error: {e}")
            return False

    def bus_open_or_check(self):
        if not self.bus.is_open:
            self.bus.open_bus()
            time.sleep(0.5)
        return self.bus.is_open

    def trigger_measurement(self):
        try:
            self.bus.write_i2c_block_data(self.address, self.measurement_register, [0x33, 0x00])
            time.sleep(0.001)
        except OSError as e:
            logging.warning(f"I2C write error: {e}")

    def poll_for_idle(self):
        while self.retries < self.max_retries:
            try:
                status = self.bus.read_i2c_block_data(self.address, self.idle_register, 2)
                if status[0] & 0x80 == 0:  # Bit 7 is 0 (idle)
                    self.retries = 0
                    return True
                self.retries += 1
                time.sleep(self.retry_interval)
            except OSError as e:
                logging.warning(f"I2C read error: {e}")
        logging.error("Failed to detect idle state after maximum retries")
        return False

    def read_data(self):
        try:
            self.trigger_measurement()
            self.poll_for_idle()
            if not self.poll_for_idle():
                return None, None, True

            raw_data = self.bus.read_i2c_block_data(self.address, self.status_register, 7)
            crc = 0
            for i in range(6):
                crc = (crc << 8) | raw_data[i]
            crc = (crc << 8) | raw_data[6]
            if crc != 0xFF:
                logging.warning("CRC mismatch, retrying...")
                return None, None, True

            humidity_raw = ((raw_data[1] << 12) | (raw_data[2] << 4) | ((raw_data[3] & 0xF0) >> 4))
            humidity = humidity_raw / (2**20) * 100
            temperature_raw = (((raw_data[3] & 0x0F) << 16) | (raw_data[4] << 8) | raw_data[5])
            temperature = temperature_raw / (2**19) * 200 - 50

            self.previous_result = (humidity, temperature)
            return humidity, temperature, False
        except OSError as e:
            logging.warning(f"I2C read error: {e}")
            return None, None, True

    def on_connect(self, client, userdata, flags, rc):
        logging.info("Connected to MQTT broker")

    def on_message(self, client, userdata, msg):
        logging.info(f"Received message: {msg.topic} - {msg.payload.decode()}")

class DHT20Context:
    def __enter__(self):
        return DHT20()

    def __exit__(self, exc_type, exc_val, exc_tb):
