from gpiozero import DOG
from picamera2 import Image
from adafruit_circuitpython_ssd1306 import OLEDDisplay
from paho.mqtt import client as mqtt_client

# Initialize logger
logging.basicConfig(filename='dog_server.log', level=logging.INFO, format='%(asctime)s - %(message)s')

class DogServer:
    def __init__(self):
        self.running = True
        self.log_file = 'dog_server.log'
        self.data_queue = []
        self.receive_thread = None
        self.cleanup_thread = None

    def init_gpio(self):
        try:
            DOG.setmode(GPIO.BCM)
            DOG.setup(DOG.IN, DOG.PULLUP)
        except Exception as e:
            logging.error(f"Failed to initialize GPIO: {e}")

    def start_receive_thread(self):
        self.receive_thread = threading.Thread(target=self._receive_loop)
        self.receive_thread.start()

    def _receive_loop(self):
        while self.running:
            try:
                data = DOG.receive()
                if data:
                    self.data_queue.append(data.decode('utf-8'))
                    logging.info(f"Received: {data}")
            except Exception as e:
                logging.error(f"Error in receive loop: {e}")
            time.sleep(0.1)

    def send_data(self, data_string):
        try:
            DOG.send(data_string.encode('utf-8'))
            logging.info(f"Sent: {data_string}")
        except Exception as e:
            logging.error(f"Error sending data: {e}")

    def write_data(self, data_string):
        with open(self.log_file, 'a') as f:
            f.write(data_string + '\n')
        logging.info(f"Written: {data_string}")

    def stop_server(self):
        self.running = False
        self.receive_thread.join()
        self.cleanup_thread.start()

    def display_log(self):
        with open(self.log_file, 'r') as f:
            logging.info(f"Log contents:\n{f.read()}")

    def help(self, command):
        if command == "start":
            self.init_gpio()
            self.start_receive_thread()
        elif command == "stop":
            self.stop_server()
        elif command == "help":
            print("Commands: start  (creates a file and starts the logging thread), stop (stops the server and the receive thread), help [command] (displays help), display (prints the contents of the log file), send <data> (sends data using DOG.send()), write <data> (writes data directly to the log file with a newline character), exit (stops the server, cleans up GPIO, and exits).")
        elif command == "display":
            self.display_log()
        elif command.startswith("send"):
            self.send_data(command.split()[1])
        elif command.startswith("write"):
            self.write_data(command.split()[1])
        else:
            print("Invalid command.")

    def exit_server(self):
        self.stop_server()
        GPIO.cleanup()
        exit(0)

def signal_handler(sig, frame):
    logging.info("Received SIGINT/SIGTERM, cleaning up and exiting...")
    DogServer().exit_server()

if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="Dog Server")
    parser.add_argument("command", choices=["start", "stop", "help", "display", "send", "write", "exit"])
    args = parser.parse_args()

    dog_server = DogServer()
    dog_server.init_gpio()
    dog_server.start_receive_thread()

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        dog_server.help(args.command)
    except Exception as e:
        logging.error(f"Error executing command: {e}")

