import threading
from gpiozero import MotionSensor
from picamera2 import PiCamera
import adafruit_circuitpython_ads1x18 as ads1x18
import paho.mqtt.client as mqtt
import json
from datetime import datetime

class SolarArrayMonitor:
    def __init__(self, poll_interval=0.5, samples=10, debounce_interval=2.0):
        self.poll_interval = poll_interval
        self.samples = samples
        self.debounce_interval = debounce_interval
        self.motion_sensor = MotionSensor(17)  # GPIO 17 (physical pin 11)
        self.debounce_timer = None
        self.occupancy_log = []
        self.mqtt_client = mqtt.Client()
        self.mqtt_client.on_connect = self.on_connect
        self.mqtt_client.on_message = self.on_message
        self.running = True
        self.thread = threading.Thread(target=self.poll_sensor)
        self.thread.daemon = True

    def on_connect(self, client, userdata, flags, rc):
        logging.info("Connected to MQTT broker")

    def on_message(self, client, userdata, msg):
        logging.info(f"Received message: {msg.topic} {msg.payload.decode()}")

    def start(self):
        self.motion_sensor.debounce_interval = self.debounce_interval
        self.motion_sensor.debounce_timer = threading.Timer(self.debounce_interval, self.motion_sensor.debounce)
        self.motion_sensor.debounce_timer.start()
        self.poll_sensor()

    def poll_sensor(self):
        while self.running:
            try:
                if self.motion_sensor.is_active:
                    self.occupancy_log.append(self.get_timestamp())
                    self.motion_sensor.clear_debounce()
                time.sleep(self.poll_interval)
            except Exception as e:
                logging.error(f"Error polling sensor: {e}")
                break

    def get_timestamp(self):
        return datetime.now().isoformat()

    def get_occupancy_stats(self):
        if not self.occupancy_log:
            return 0
        return len(self.occupancy_log)

    def stop(self):
        self.motion_sensor.debounce_timer.cancel()
        self.running = False
        self.motion_sensor.close()
        self.mqtt_client.disconnect()

    def run(self):
        try:
            self.start()
            while self.running:
                time.sleep(1)
        except Exception as e:
            logging.error(f"Initialization failed: {e}")
            self.running = False
            self.motion_sensor.close()
            self.mqtt_client.disconnect()
            exit(1)
        self.stop()
        self.mqtt_client.loop_forever()

if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)
    monitor = SolarArrayMonitor()
    try:
        monitor.run()
    except KeyboardInterrupt:
        monitor.stop()
        exit(0)

import pigpio
import threading
import time
import signal

class OutputPin:
    def __init__(self, gpio, value_list=(0, 1)):
        self.gpio = gpio
        self.value_list = value_list
        self.value = value_list[0]
        self.pigpio.pi()
        self.connect()

    def connect(self):
        try:
            self.pigpio.set_mode(self.gpio, pigpio.OUTPUT)
        except pigpio.PiGPIOError as e:
            print(f"Error connecting to GPIO {self.gpio}: {e}")
            self.pigpio.stop()
            self.pigpio.init()
            self.connect()

    def shutdown(self):
        try:
            self.pigpio.set_mode(self.gpio, pigpio.INPUT)
        except pigpio.PiGPIOError as e:
            print(f"Error setting GPIO {self.gpio} to input mode: {e}")
        finally:
            self.pigpio.stop()

    def set_value(self, value):
        if value not in self.value_list:
            raise ValueError("Value must be in value_list")
        self.value = value
        print(f"Pin {self.gpio} set to {self.value}")

class TriggerPin(OutputPin):
    def __init__(self, gpio, pulse_duration=100e-6, pulse_high=True):
        super().__init__(gpio)
        self.pulse_duration = pulse_duration
        self.pulse_high = pulse_high
        self.trigger_thread = None
        self.lock = threading.Lock()

    def trigger(self):
        try:
            with self.lock:
                self.set_value(self.pulse_high)
                time.sleep(self.pulse_duration)
                self.set_value(False)
        except Exception as e:
            print(f"Error generating pulse: {e}")

    def start_trigger(self):
        self.trigger_thread = threading.Thread(target=self.trigger)
        self.trigger_thread.start()

    def stop_trigger(self):
        if self.trigger_thread:
            self.trigger_thread.join()
            self.trigger_thread = None

def signal_handler(signal, frame):
    print("\nReceived signal, shutting down GPIO...")
    ExampleOutput.shutdown()
    ExampleTrigger.shutdown()
    print("GPIO resources released.")

