        self.clock_pin = clock_pin
        self.data_pin = data_pin
        self.callback = callback
        self.prev_clock = 0
        self.counter = 0
        self.debounce_timer = None
        self.debounce_interval = 0.005

    def _debounce(self):
        global self.prev_clock
        while time.monotonic() - self.prev_clock < self.debounce_interval:
            time.sleep(0.001)
        self.prev_clock = time.monotonic()

    def _read_encoder(self):
        self._debounce()
        self.counter += 1 if self.data_pin == 1 else -1
        if self.data_pin != self.prev_clock:
            self.callback(self.counter) if self.callback else None
        self.prev_clock = time.monotonic()

    def start(self):
        self.debounce_timer = threading.Timer(self.debounce_interval, self._debounce)
        self.debounce_timer.start()

    def stop(self):
        self.debounce_timer.cancel()

    def cleanup(self):
        GPIOZero.cleanup()

