            raise ValueError("Duty cycle must be between 0 and 100.")
        if display_time <= 0:
            raise ValueError("Display time must be greater than 0.")

        price_str = "{:.2f}".format(price)
        digits = price_str.split('.')
        if len(digits) != 2 or float(digits[0]) < 0 or float(digits[0]) > 99.99:
