import time
import logging
import gpiozero
import paho.mqtt.client as mqtt
from gpiozero import PWMOutputDevice
from picamera2 import PiCamera

# Configure logging
logging.basicConfig(level=logging.INFO)

class MotorShield:
    def __init__(self):
        self.motors = [
            {'pin': 13, 'directions': [0b00000010, 0b00000001, 0b00000000]},  # Motor 1
            {'pin': 12, 'directions': [0b00001000, 0b00000100, 0b00000000]}  # Motor 2
        ]
        self.pwm_devices = [PWMOutputDevice(self.motors[0]['pin'], frequency=100),
                           PWMOutputDevice(self.motors[1]['pin'], frequency=100)]

    def add_motor(self, motor_pin, directions):
        self.motors.append({'pin': motor_pin, 'directions': directions})

    def start(self, motor_index, duty_cycle):
        if motor_index < 0 or motor_index >= len(self.motors):
            raise IndexError("Invalid motor index")

        motor = self.motors[motor_index]
        if duty_cycle < 0 or duty_cycle > 100:
            raise ValueError("Duty cycle must be between 0 and 100")

        logging.info(f"Starting motor {motor_index + 1} with {duty_cycle}% duty cycle")
        self.pwm_devices[motor_index].start(duty_cycle)

    def stop(self, motor_index):
        if motor_index < 0 or motor_index >= len(self.motors):
            raise IndexError("Invalid motor index")

        logging.info(f"Stopping motor {motor_index + 1}")
        self.pwm_devices[motor_index].stop()

    def change_duty_cycle(self, motor_index, new_duty_cycle):
        if motor_index < 0 or motor_index >= len(self.motors):
            raise IndexError("Invalid motor index")

        if new_duty_cycle < 0 or new_duty_cycle > 100:
            raise ValueError("Duty cycle must be between 0 and 100")

        logging.info(f"Changing duty cycle of motor {motor_index + 1} to {new_duty_cycle}%")
        self.pwm_devices[motor_index].duty_cycle = new_duty_cycle

    def stop_all_motors(self):
        for device in self.pwm_devices:
            device.stop()
        logging.info("All motors stopped")

class Motor:
    def __init__(self, shield):
        self.shield = shield

    def __enter__(self):
        return self.shield

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.shield.stop_all_motors()

def on_connect(client, userdata, flags, rc):
    logging.info("Connected to MQTT broker")

def on_message(client, userdata, msg):
    logging.info(f"Received message: {msg.payload.decode()}")

def main():
    logging.basicConfig(level=logging.INFO)

    shield = MotorShield()
    shield.add_motor(11, 0b00000010)  # Motor 1
    shield.add_motor(10, 0b00000001)  # Motor 2

    with MotorShield(shield) as shield:
        try:
            shield.start(0, 75)  # Start Motor 1 clockwise at 75% duty cycle
            shield.start(1, 50)  # Start Motor 2 counter-clockwise at 50% duty cycle
            time.sleep(5)  # Wait for 5 seconds
            shield.change_duty_cycle(0, 25)  # Change Motor 1's duty cycle to 25%
            time.sleep(2)  # Wait for 2 seconds
            shield.stop_all_motors()  # Stop all motors
        except Exception as e:
            logging.error(f"An error occurred: {e}")

    # Clean up GPIO resources on exit
    shield.stop_all_motors()

if __name__ == "__main__":
    client = mqtt.Client()
    client.on_connect = on_connect
    client.on_message = on_message
    client.connect("mqtt.example.com", 1883, 60)
    client.subscribe("test/topic")

    try:
        main()
    except KeyboardInterrupt:
        client.loop_stop()
        logging.info("Exiting gracefully")
    finally:
        client.disconnect()

