import time
import logging
import signal
import atexit
from Adafruit_MotorHAT import DC_Motor, I2C_BUS, PCA9685
from gpiozero import Button
import paho.mqtt.client as mqtt

class DCMotorHATExtra(DC_Motor):
    def __init__(self, i2c_bus=I2C_BUS.I2C_1, i2c_addr=0x60, pwm_freq=60):
        super().__init__(i2c_bus, i2c_addr)
        self.pwm_freq = pwm_freq
        self.pwm = PCA9685(self.i2c_bus, self.i2c_addr)
        self.pwm.frequency = self.pwm_freq
        self.pwm.duty_cycle = 0
        self.last_duty_cycle = 0
        self.motors = [self]

    def set_pwm_freq(self, freq):
        if freq != self.pwm_freq:
            self.pwm_freq = freq
            self.pwm.frequency = freq

    def get_pwm_freq(self):
        return self.pwm_freq

    def release(self):
        for motor in self.motors:
            motor.release()

class DCMotor:
    def __init__(self, dcm_hat, motor_num, pwm_freq=60, invert=False):
        if not isinstance(dcm_hat, DCMotorHATExtra):
            raise ValueError("dcm_hat must be an instance of DCMotorHATExtra")
        if motor_num < 1 or motor_num > 4:
            raise ValueError("Motor number must be between 1 and 4")
        self.dcm_hat = dcm_hat
        self.motor_num = motor_num
        self.pwm_freq = pwm_freq
        self.invert = invert

    def set_dc(self, duty_cycle):
        if not 255 >= abs(duty_cycle) >= -255:
            raise ValueError("Duty cycle must be between -255 and 255")
        self.duty_cycle = duty_cycle % 256
        if self.duty_cycle == 0:
            self.dcm_hat.release()
        else:
            self.dcm_hat.set_pwm(self.motor_num - 1, self.duty_cycle, self.invert)

    def stop(self):
        self.dcm_hat.release()

    def close(self):
        self.dcm_hat.release()

    def get_status(self):
        return {
            "motor_num": self.motor_num,
            "pwm_freq": self.dcm_hat.get_pwm_freq(),
            "invert": self.invert,
            "last_duty_cycle": self.last_duty_cycle
        }

def signal_handler(signal, frame):
    logging.info("Received signal, shutting down...")
    for motor in DCMotorHATExtra.dcm_hat.motors:
        motor.stop()

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

def on_connect(client, userdata, flags, rc):
    logging.info("Connected to MQTT broker")

def on_message(client, userdata, msg):
    logging.info(f"Received message: {msg.payload.decode()}")

mqtt_client = mqtt.Client()
mqtt_client.on_connect = on_connect
mqtt_client.on_message = on_message
mqtt_client.connect("mqtt.example.com", 1883, 60)

def on_exit(signum, frame):
    logging.info("Exiting...")
    for motor in DCMotorHATExtra.dcm_hat.motors:
        motor.stop()

atexit.register(on_exit, signal.SIGINT, signal.SIGTERM)

# Usage example
try:
    dcm_hat = DCMotorHATExtra(i2c_bus=I2C_BUS.I2C_1, i2c_addr=0x60)
    motor = DCMotor(dcm_hat, 1)

    for i in range(100, 0, -1):
        motor.set_dc(i)
        time.sleep(0.1)

    motor.set_dc(0)
    motor.stop()
    motor.close()

except Exception as e:
    logging.error(f"An error occurred: {e}")

