import RPi.GPIO as GPIO
import time
import logging
import paho.mqtt.client as mqtt

# Configure logging
logging.basicConfig(level=logging.INFO)

# GPIO setup
GPIO.setmode(GPIO.BCM)
PWM_PIN = 12
FORWARD_PIN = 20
REVERSE_PIN = 21

def setup_gpio():
    try:
        GPIO.setup(FORWARD_PIN, GPIO.OUT)
        GPIO.setup(REVERSE_PIN, GPIO.OUT)
        GPIO.setup(PWM_PIN, GPIO.PWM)
        pwm = GPIO.PWM(PWM_PIN, 100)  # 100 Hz PWM frequency
        pwm.start(0)  # Initial duty cycle 0%

        logging.info("GPIO setup complete.")
    except Exception as e:
        logging.error(f"GPIO setup failed: {e}")

def set_direction(direction):
    try:
        if direction == 'forward':
            GPIO.output(FORWARD_PIN, GPIO.HIGH)
        elif direction == 'reverse':
            GPIO.output(FORWARD_PIN, GPIO.LOW)
        else:
            logging.error("Invalid direction. Please choose 'forward' or 'reverse'.")
    except Exception as e:
        logging.error(f"Direction setting failed: {e}")

def ramp_speed(start_duty, end_duty, steps=30):
    try:
        for duty in range(start_duty, end_duty + 1, steps):
            pwm.ChangeDutyCycle(duty)
            time.sleep(0.030)  # 30 ms step delay
        logging.info("Speed ramp complete.")
    except Exception as e:
        logging.error(f"Speed ramp failed: {e}")

def stop_motor():
    try:
        pwm.stop()
        logging.info("Motor stopped.")
    except Exception as e:
        logging.error(f"Motor stop failed: {e}")

def mqtt_connect(topic, client_id):
    try:
        client = mqtt.Client(client_id)
        client.connect("mqtt.server_address", 1883)
        logging.info("Connected to MQTT broker.")
        return client
    except Exception as e:
        logging.error(f"MQTT connection failed: {e}")
        return None

def mqtt_publish(client, topic, message):
    try:
        client.publish(topic, message)
        logging.info(f"Published message: {message}")
    except Exception as e:
        logging.error(f"MQTT publish failed: {e}")

def main():
    setup_gpio()

    while True:
        direction = input("Enter direction (forward/reverse): ").strip().lower()
        set_direction(direction)

        try:
            start_duty = 0
            end_duty = 80
            ramp_speed(start_duty, end_duty)
        except KeyboardInterrupt:
            stop_motor()
            logging.info("Program interrupted by user.")
            break

        # Example MQTT publish
        client = mqtt_connect("art_installation/motor_control", "rpi_motor_control")
        if client:
            mqtt_publish(client, "speed", f"{start_duty}%")
            client.disconnect()

if __name__ == "__main__":
    main()

