from paho.mqtt import client as mqttClient

class MotorError(Exception):
    pass

class Motor:
    def __init__(self, pigpio_instance, pin):
        if not isinstance(pigpio_instance, pigpio.pi):
            raise MotorError("Invalid pigpio.pi instance")
        if not 0 <= pin < 36:  # GPIO 0-35
            raise MotorError("Invalid GPIO pin number")
        self.pi = pigpio_instance
        self.pin = pin
        self.pi.set_mode(self.pin, pigpio.OUTPUT)
        self.frequency = 1000
        self.duty_cycle = 0

    def set_frequency(self, freq):
        if not isinstance(freq, int) or freq < 0:
            raise MotorError("Frequency must be a non-negative integer")
        self.frequency = freq
        self.pi.set_pwm_freq(self.pin, self.frequency)

    def set_duty_cycle(self, duty):
        if not isinstance(duty, int) or not 0 <= duty <= 255:
            raise MotorError("Duty cycle must be an integer between 0 and 255")
        self.duty_cycle = duty
        self.pi.set_pwm(self.pin, 0, self.duty_cycle)

    def stop(self):
        self.set_duty_cycle(0)

    def close(self):
        self.pi.stop()

# Example usage with MQTT for remote control
class MQTTMotorController:
    def __init__(self, mqtt_host, mqtt_port, topic, motor_id):
        self.mqtt_host = mqtt_host
        self.mqtt_port = mqtt_port
        self.topic = topic
        self.motor_id = motor_id
        self.client = mqttClient.Client()
        self.client.on_connect = self.on_connect
        self.client.on_message = self.on_message

    def on_connect(self, client, userdata, flags, rc):
        if rc == 0:
            print("Connected to MQTT broker")
            self.client.subscribe(self.topic)

    def on_message(self, client, userdata, msg):
        if msg.topic == self.topic:
            motor_id = int(msg.payload.decode())
            if motor_id == self.motor_id:
                try:
                    motor = Motor(pigpio.pi(), motor_id)
                    command = msg.payload.decode()
                    if command == "start":
                        motor.start()
                    elif command == "stop":
                        motor.stop()
                except MotorError as e:
                    print(f"Error: {e}")

# Example usage
