import RPi.GPIO as GPIO
import time
import logging
import threading
from datetime import datetime

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class ServoController:
    def __init__(self, gpio_pin=18):
        try:
            GPIO.setmode(GPIO.BCM)
            self.servo_pin = gpio_pin
            GPIO.setup(self.servo_pin, GPIO.OUT)
            logging.info(f"Servo initialized on GPIO {self.servo_pin}")
        except GPIOError as e:
            logging.error(f"Failed to initialize GPIO: {e}")
            raise

    def _angle_to_duty_cycle(self, angle):
        # Assuming a full range of 180 degrees, 2.5% for 0 degrees, 12.5% for 180 degrees
        return 2.5 + (angle / 180) * 12.5

    def move_to(self, angle):
        try:
            duty_cycle = self._angle_to_duty_cycle(angle)
            GPIO.output(self.servo_pin, True)
            time.sleep(0.001)  # PWM duty cycle update period
            GPIO.output(self.servo_pin, False)
            time.sleep(duty_cycle * 0.01)  # PWM period
        except Exception as e:
            logging.error(f"Error moving to angle {angle}: {e}")

    def stop(self):
        GPIO.output(self.servo_pin, False)

    def sweep_and_log(self, angles):
        try:
            for angle in angles:
                self.move_to(angle)
                time.sleep(0.5)  # Pause for observation
                logging.info(f"Servo at {angle} degrees at {datetime.now()}")
        except KeyboardInterrupt:
            self.stop()
            logging.info("Servo control stopped by user")
        finally:
            self.stop()
            GPIO.cleanup()

def main(angles):
    servo_controller = ServoController()
    servo_controller.sweep_and_log(angles)

if __name__ == "__main__":
    angles_to_sweep = [0, 45, 90, 135, 180, 225, 270, 315]
    main(angles_to_sweep)

