import serial
import time
import logging
from pymodbus.client.sync import ModbusTcpClient

class ServoController:
    def __init__(self, port='/dev/serial0', baudrate=115200, timeout=1):
        self.ser = serial.Serial(port, baudrate, timeout=timeout)
        self.modbus_client = ModbusTcpClient(self.ser.name, ip='127.0.0.1', port=502)
        self.modbus_client.connect()

        self.CONTROL_MAP = {
            'R/W': 'R',
            'Register': 0x3100,
            'functioncode': 3,
            'Value': {'Stop': 0x0006, 'Start': 0x000F}
        }

        self.STATUS_MAP = {
            'R/W': 'R',
            'Register': 0x3000,
            'functioncode': 3,
            'read_length': 1
        }

        self.OPMODE_MAP = {
            'R/W': 'R',
            'Register': 0x3500,
            'functioncode': 6,
            'Value': {'Position': 1}
        }

        self.POSITION_FEEDBACK_MAP = {
            'R/W': 'R',
            'Register': 0x3700,
            'read_length': 2
        }

        self.VELOCITY_FEEDBACK_MAP = {
            'R/W': 'R',
            'Register': 0x3B00,
            'read_length': 2
        }

        self.POSITION_COMMAND_MAP = {
            'W': 0x4000
        }

        self.VELOCITY_COMMAND_MAP = {
            'W': 0x6F00
        }

    def set_control_mode(self, mode):
        try:
            self.modbus_client.write_register(self.CONTROL_MAP['Register'], self.CONTROL_MAP['functioncode'], 0, mode)
        except (serial.SerialException, ModbusTcpClient.ModbusException) as e:
            logging.error(f"Error setting control mode: {e}")

    def get_status(self):
        try:
            status = self.modbus_client.read_holding_registers(self.STATUS_MAP['Register'], 1, self.STATUS_MAP['read_length'])
            return status
        except (serial.SerialException, ModbusTcpClient.ModbusException) as e:
            logging.error(f"Error reading status: {e}")
            return None

    def set_opmode(self, position_mode):
        try:
            self.modbus_client.write_register(self.OPMODE_MAP['Register'], self.OPMODE_MAP['functioncode'], 0, position_mode)
        except (serial.SerialException, ModbusTcpClient.ModbusException) as e:
            logging.error(f"Error setting opmode: {e}")

    def get_position_feedback(self):
        try:
            feedback = self.modbus_client.read_holding_registers(self.POSITION_FEEDBACK_MAP['Register'], 2, self.POSITION_FEEDBACK_MAP['read_length'])
            return feedback
        except (serial.SerialException, ModbusTcpClient.ModbusException) as e:
            logging.error(f"Error reading position feedback: {e}")
            return None

    def get_velocity_feedback(self):
        try:
            feedback = self.modbus_client.read_holding_registers(self.VELOCITY_FEEDBACK_MAP['Register'], 2, self.VELOCITY_FEEDBACK_MAP['read_length'])
            return feedback
        except (serial.SerialException, ModbusTcpClient.ModbusException) as e:
            logging.error(f"Error reading velocity feedback: {e}")
            return None

    def set_position_command(self, position):
        try:
            self.modbus_client.write_register(self.POSITION_COMMAND_MAP['Register'], self.POSITION_COMMAND_MAP['functioncode'], 0, position)
        except (serial.SerialException, ModbusTcpClient.ModbusException) as e:
            logging.error(f"Error setting position command: {e}")

    def set_velocity_command(self, velocity):
        try:
            self.modbus_client.write_register(self.VELOCITY_COMMAND_MAP['Register'], self.VELOCITY_COMMAND_MAP['functioncode'], 0, velocity)
        except (serial.SerialException, ModbusTcpClient.ModbusException) as e:
            logging.error(f"Error setting velocity command: {e}")

    def close(self):
        self.ser.close()
        self.modbus_client.close()

if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)
    servo_controller = ServoController()

    # Example usage
    servo_controller.set_control_mode(1)  # Start mode
    servo_controller.set_opmode(1)  # Position mode
    servo_controller.set_position_command(100)  # Command position
    time.sleep(2)
    print(f"Position: {servo_controller.get_position_feedback()}")

    servo_controller.close()

