            raise Exception("Serial port is not open.")
        try:
            return self.modbus_rtu.read_register(0x3700)
        except ModbusException as e:
            logging.error(f"Error reading position feedback: {e}")
            return None

    def read_velocity_feedback(self):
        if not self.ser.is_open:
            raise Exception("Serial port is not open.")
        try:
            return self.modbus_rtu.read_register(0x3B00)
        except ModbusException as e:
            logging.error(f"Error reading velocity feedback: {e}")
