        if not self.ser.is_open:
            raise Exception("Serial port is not open.")
        try:
            return self.modbus_rtu.read_register(0x3000)
        except ModbusException as e:
            logging.error(f"Error reading status: {e}")
            return None

    def write_command(self, register, value):
        if not self.ser.is_open:
            raise Exception("Serial port is not open.")
        try:
            self.modbus_rtu.write_register(register, value)
        except ModbusException as e:
            logging.error(f"Error writing to register: {e}")

