        logging.info("Connected to MQTT broker")

    def on_message(client, userdata, msg):
        logging.info(f"Received message: {msg.payload.decode()}")

    def mqtt_connect(self, broker='mqtt.eclipse.org', port=1883, client_id='RaspberryPiServo'):
        client = mqtt.Client(client_id)
        client.on_connect = self.on_connect
        client.on_message = self.on_message
        mqtt.connect(broker, port, 60)
        client.loop_start()

def main():
    try:
        controller = ModbusServoController()
        controller.mqtt_connect()

        try:
            controller.start()
            time.sleep(2)  # Servo movement
            controller.write_position_command(100)
            position_feedback = controller.read_position_feedback()
            velocity_feedback = controller.read_velocity_feedback()
            status = controller.read_status()
            print(f"Position: {position_feedback}, Velocity: {velocity_feedback}, Status: {status}")
        except Exception as e:
            logging.error(f"An error occurred: {e}")
        finally:
            controller.stop()
            controller.ser.close()
            client.loop_stop()

if __name__ == '__main__':
