import time
import adafruit_servokit
import pytest

# Mock ServoKit for testing
class MockServoKit:
    def __init__(self, kit_num, servo_num):
        if servo_num < 0 or servo_num > 15:
            raise ValueError("Invalid servo number")
        if kit_num != 0:
            raise ValueError("Incorrect kit number")
        self.kit = adafruit_servokit.ServoKit(kit_num, i2c_address=0x40)

    def grab_object(self, servo_num):
        try:
            self.kit.servo[servo_num].angle = 90
            return True
        except Exception as e:
            print(f"Error during grab: {e}")
            return False

    def release_object(self, servo_num):
        try:
            self.kit.servo[servo_num].angle = 150
            return True
        except Exception as e:
            print(f"Error during release: {e}")
            return False

    def move_servo(self, servo_num, target_angle):
        if target_angle < 0 or target_angle > 180:
            raise ValueError("Invalid target angle")
        if servo_num < 0 or servo_num > 15:
            raise ValueError("Invalid servo number")

        delay = 0.04
        for angle in range(self.kit.servo[servo_num].angle, target_angle + 1, 5):
            try:
                self.kit.servo[servo_num].angle = angle
                time.sleep(delay)
            except Exception as e:
                print(f"Error during movement: {e}")
                return False

        return True

# Test function to simulate the real environment
@pytest.mark.usefixtures("mocker")
def test_servo_control():
    mocker.patch("adafruit_servokit.ServoKit.__init__", MockServoKit)

    kit = MockServoKit(0, 0)

    # Grab and move servo
    assert kit.grab_object(0)
    kit.move_servo(0, 90)
    assert kit.move_servo(0, 180)

    # Release servo
    kit.release_object(0)

if __name__ == "__main__":
    try:
        test_servo_control()
    except KeyboardInterrupt:
        print("\nExiting gracefully...")
    finally:
        # Release resources
        if hasattr(kit, "kit"):
            kit.kit.close()

