import logging
import gpiozero
from gpiozero import OutputDevice
import paho.mqtt.client as mqtt

# Configure logging
logging.basicConfig(level=logging.INFO)

# Define actuators
pump = OutputDevice(20)  # BCM GPIO20 for the nutrient pump
light = OutputDevice(21)  # BCM GPIO21 for the grow light

# Helper function for case-insensitive keyword matching
def match_intent(phrase, intents):
    for intent in intents:
        if intent.lower() in phrase.lower():
            return intent
    return None

# Intent mapping
intents = {
    "pump_on": pump.on,
    "pump_off": pump.off,
    "light_toggle": light.toggle
}

# MQTT setup (optional, for remote control)
mqtt_client = mqtt.Client()
mqtt_client.on_connect = on_connect
mqtt_client.connect("mqtt.example.com", 1883, 60)

def on_connect(client, userdata, flags, rc):
    logging.info("Connected to MQTT broker")

# Parse phrases and actuate
test_phrases = ["turn the pump on", "switch the light", "turn pump off", "unknown command"]

for phrase in test_phrases:
    intent = match_intent(phrase, intents.keys())
    if intent:
        try:
            logging.info(f"Received intent: {phrase}")
            if intent == "pump_on":
                intents[intent]()
                logging.info(f"Applied: Pump ON")
            elif intent == "pump_off":
                intents[intent]()
                logging.info(f"Applied: Pump OFF")
            elif intent == "light_toggle":
                intents[intent]()
                logging.info(f"Applied: Light TOGGLED")
        except Exception as e:
            logging.warning(f"Error processing intent: {e}")
    else:
        logging.warning(f"Unknown intent: {phrase}")

# Ensure safe actuator shutdown
try:
    pump.close()
    light.close()
except Exception as e:
    logging.error(f"Error closing actuators: {e}")

# Handle KeyboardInterrupt or exceptions
try:
    while True:
        pass
except KeyboardInterrupt:
    pump.close()
    light.close()
    logging.info("Exiting gracefully")
except Exception as e:
    logging.error(f"An error occurred: {e}")

