        try:
            seconds = self.i2c.read_byte_data(self.address, 0x00)
            return seconds & 0x3F  # Convert to BCD
        except smbus2.SMBus2Error as e:
            print(f"Error reading seconds: {e}")
            return None

    def write_seconds(self, seconds):
        if not 0 <= seconds <= 59:
            raise ValueError("Seconds must be between 0 and 59.")
        try:
            self.i2c.write_byte_data(self.address, 0x00, seconds)
        except smbus2.SMBus2Error as e:
            print(f"Error writing seconds: {e}")

    def read_minutes(self):
        try:
            minutes = self.i2c.read_byte_data(self.address, 0x01)
            return minutes & 0x3F  # Convert to BCD
        except smbus2.SMBus2Error as e:
            print(f"Error reading minutes: {e}")
            return None

    def write_minutes(self, minutes):
        if not 0 <= minutes <= 59:
            raise ValueError("Minutes must be between 0 and 59.")
        try:
            self.i2c.write_byte_data(self.address, 0x01, minutes)
        except smbus2.SMBus2Error as e:
            print(f"Error writing minutes: {e}")

