        except smbus2.SMBus2Error as e:
            print(f"Error writing year: {e}")

    def read_datetime(self, century=21):
        try:
            seconds = self.read_seconds()
            minutes = self.read_minutes()
            hours = self.read_hours()
            date = self.read_date()
