            year = self.read_year()

            return datetime(century, month, date, hours, minutes, seconds)
        except ValueError as e:
            print(f"Error reading datetime: {e}")
            return None

    def write_all(self, century=21, seconds=None, minutes=None, hours=None, date=None, month=None, year=None):
