                    format='%(asctime)s - %(message)s')

# CO2 concentration threshold in ppm
CO2_THRESHOLD = 500

def read_co2_sensor():
    try:
        ser = serial.Serial('/dev/ttyUSB0', 9600, timeout=1)
        if not ser.is_open:
            raise SerialException("Serial port failed to open.")

        try:
            data = ser.readline().decode('utf-8').strip()
            if not data:
                raise ValueError("Received empty data.")

            try:
                concentration = int(data)
                if concentration < 0:
                    raise ValueError("CO2 concentration cannot be negative.")
                if concentration > 1000:  # Assuming max CO2 concentration is 1000 ppm
                    raise ValueError("CO2 concentration exceeds threshold.")
            except ValueError:
                print("Error: Invalid CO2 concentration data received.")
                return None

            logging.info(f"{datetime.datetime.now():%Y-%m-%d %H:%M:%S} - CO2 Concentration: {concentration} ppm")
            return concentration

        except SerialException as e:
            print(f"Serial error: {e}")
        except IOError as e:
            print(f"IO error: {e}")
        finally:
            ser.close()

    except Exception as e:
        print(f"An unexpected error occurred: {e}")

def mqtt_publish(topic, payload):
    client = mqtt.Client()
    client.connect("mqtt.server.com", 1883)  # Replace with your MQTT broker
    client.publish(topic, payload)
    client.disconnect()

