import serial
import time
from dataclasses import dataclass
import logging
import threading
import paho.mqtt.client as mqtt

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

@dataclass
class GPS_readings:
    latitude: float
    longitude: float
    altitude: int
    satellite_count: int

class GPSReader:
    def __init__(self):
        self.serial_port = '/dev/serial0'
        self.baudrate = 9600
        self.timeout = 1
        self.serial_connection = None
        self.running = True
        self.stop_event = threading.Event()

    def connect(self):
        try:
            self.serial_connection = serial.Serial(self.serial_port, self.baudrate, timeout=self.timeout)
            logging.info(f"Connected to GPS device at {self.serial_port}")
        except serial.SerialException as e:
            logging.error(f"Failed to connect to GPS device: {e}")

    def disconnect(self):
        if self.serial_connection:
            self.serial_connection.close()
            logging.info("Disconnected from GPS device")

    def run(self):
        while self.running:
            if not self.stop_event.is_set():
                try:
                    line = self.serial_connection.readline().decode('utf-8').strip()
                    if line and line.startswith('$GPGGA'):
                        gps_data = self.parse_gpgga(line)
                        logging.info(f"GPS Reading: {gps_data}")
                except serial.SerialException as e:
                    logging.error(f"Serial read error: {e}")
                except ValueError as e:
                    logging.error(f"Invalid GPGGA sentence: {e}")
                except Exception as e:
                    logging.error(f"Unexpected error: {e}")

            time.sleep(0.1)

    def parse_gpgga(self, line: str) -> GPS_readings:
        try:
            fields = line.split(',')
            if len(fields) < 7:
                logging.warning("Invalid GPGGA sentence: too few fields")
                return GPS_readings(None, None, None, None)

            lat_str, lon_str, alt, sats, checksum = fields[2:7]
            lat_dec = float(lat_str[:-2]) / 100.0 + float(lat_str[-2:]) / 10000.0
            lon_dec = float(lon_str[:-2]) / 100.0 + float(lon_str[-2:]) / 10000.0
            alt_m = int(alt.rstrip('Z'))
            sats_count = int(sats.rstrip('S'))

            if checksum != fields[6]:
                logging.warning("Invalid GPGGA checksum")
                return GPS_readings(None, None, None, None)

            return GPS_readings(lat_dec, lon_dec, alt_m, sats_count)

    def on_connect(client, userdata, flags, rc):
        logging.info("GPSReader MQTT client connected")

    def on_message(client, userdata, msg):
        logging.info(f"Received MQTT message: {msg.payload.decode()}")

    def on_log(self, client, userdata, level, buf):
        logging.info(buf)

    def on_disconnect(client, userdata, code, reasonstr):
        logging.info(f"MQTT client disconnected: {reasonstr}")

    def start_mqtt(self):
        client = mqtt.Client()
        client.on_connect = self.on_connect
        client.on_message = self.on_message
        client.on_log = self.on_log
        client.on_disconnect = self.on_disconnect

        client.connect("mqtt.example.com", 1883, 60)
        client.loop_start()

if __name__ == "__main__":
    reader = GPSReader()
    reader.connect()
    reader.start_mqtt()
    threading.Thread(target=reader.run, daemon=True).start()

    # To stop the program, send SIGINT (Ctrl+C) or SIGTERM
    try:
