import serial
import time
import paho.mqtt.client as mqtt

class GPSController:
    def __init__(self, port='/dev/ttyAMA0', baud=9600):
        self.port = port
        self.baudrate = baud
        self.serial_port = None
        self.mqtt_client = mqtt.Client()
        self.mqtt_client.on_connect = self.on_connect
        self.mqtt_client.on_message = self.on_message

    def __enter__(self):
        self.serial_port = serial.Serial(self.port, self.baudrate, timeout=1)
        self.serial_port.open()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.close()

    def attach(self):
        try:
            self.serial_port.write(b'AT+CGNSPWR=1\r\n')
            time.sleep(1)
            self.serial_port.flush()
        except serial.SerialException as e:
            print(f"Error while powering on GNSS: {e}")

    def detach(self):
        try:
            self.serial_port.write(b'AT+CGNSPWR=0\r\n')
            self.serial_port.flush()
        except serial.SerialException as e:
            print(f"Error while powering off GNSS: {e}")

    def get_data(self):
        try:
            if self.serial_port:
                data = self.serial_port.readline().decode('utf-8').strip()
                if data.startswith('$GPRMC'):
                    parts = data.split(',')
                    if len(parts) >= 6 and parts[2] == 'A':
                        return parts
                    else:
                        print("Invalid or incomplete GPS data received.")
                else:
                    print("No valid GPS data received.")
            return None
        except serial.SerialException as e:
            print(f"Error while reading from GPS: {e}")

    def on_connect(self, client, userdata, flags, rc):
        print("Connected to MQTT broker with result code "+str(rc))

    def on_message(self, client, userdata, msg):
        print(f"Received message: {msg.topic} - {msg.payload.decode()}")

# Usage with a context manager
with GPSController() as gps:
    gps.attach()
    gps.mqtt_client.connect("mqtt.eclipse.org", 1883)
    gps.mqtt_client.subscribe("gps/data")
    gps.mqtt_client.loop_forever()

