        try:
            self.connection = serial.Serial(self.serial_port, self.baud_rate, timeout=1)
            if not self.connection.is_open:
                raise SerialException("Failed to open serial port.")
            logging.info("Connected to GPS device.")
            return True
        except (serial.SerialException, OSError) as e:
            logging.error(f"Error connecting to GPS device: {e}")
            return False

    def read_data(self):
        if not self.connection:
            return None
        try:
            data = self.connection.read(1024).decode('utf-8').strip()
            if not data:
                return None
            return data
        except Exception as e:
            logging.error(f"Error reading data: {e}")
            return None

    def parse_gga(self, data):
        if not data:
            return None

        gga_pattern = re.compile(r'$(GPGGA|GNGGA) (\d{3}) (\d{3}) (\d{3}) (\d{3}) (\d{3}) (\d{3}) (\d{3}) ([A-Z]{3}) ([+-]\d{2}) (\d{3}) (\d{3})')
        match = gga_pattern.search(data)
        if not match:
            logging.error("Invalid NMEA sentence format.")
            return None

        talker_id = match.group(1)
        if talker_id == 'GPGGA':
            sentence = data
        elif talker_id == 'GNGGA':
            sentence = data

        try:
            utc_time = match.group(2) + ' ' + match.group(3) + ' ' + match.group(4)
            latitude = float(match.group(5))
            longitude = float(match.group(6))
            fix_quality = match.group(7)
            num_satellites = int(match.group(8))
        except (IndexError, ValueError):
            logging.error("Malformed NMEA sentence.")
            return None

        return {
            'utc_time': utc_time,
            'latitude': latitude,
            'longitude': longitude,
            'fix_quality': fix_quality,
            'num_satellites': num_satellites
        }

    def close(self):
        if self.connection and self.connection.is_open:
            try:
                self.connection.close()
                logging.info("Serial connection closed.")
                self.connection = None
            except Exception as e:
                logging.error(f"Error closing serial connection: {e}")

class SerialException(Exception):
    pass

