    gps = SimpleGPS()

    if gps.connect():
        while True:
            data = gps.read_data()
            if data:
                parsed_data = gps.parse_gga(data)
                if parsed_data:
                    logging.info(f"Parsed GPS data: {parsed_data}")
            time.sleep(1)

    gps.close()

if __name__ == "__main__":
    main()

