import threading
import socket
from flask import Flask, request, jsonify, abort
import serial
from gpiozero import Button
import time
import paho.mqtt.client as mqtt

class SerialCommunicator:
    def __init__(self):
        self.lock = threading.Lock()
        self.ser = None

    def open(self, port, baudrate):
        try:
            self.ser = serial.Serial(port, baudrate, timeout=1)
        except serial.SerialException as e:
            raise e

    def send(self, cmd):
        cmd_ascii = cmd.encode('ascii')
        self.ser.write(cmd_ascii)
        self.ser.flush()

    def receive_line(self):
        start_time = time.time()
        while True:
            try:
                line = self.ser.readline().decode('utf-8').strip()
                if line:
                    return line
                if time.time() - start_time > 1:
                    raise socket.timeout
            except socket.timeout:
                return None

    def close(self):
        if self.ser:
            self.ser.close()
            self.ser = None

class DataManager:
    def __init__(self):
        self.data = [
            {"id": 1, "name": "Item1", "done": False},
            {"id": 2, "name": "Item2", "done": True}
        ]
        self.lock = threading.Lock()

    def get_all(self):
        return [item for item in self.data]

    def get_by_id(self, item_id):
        for item in self.data:
            if item["id"] == item_id:
                return item
        abort(404)

    def create(self, name, done):
        if not name or not isinstance(name, str):
            abort(400)
        if not isinstance(done, bool):
            abort(400)

        new_item = {"id": len(self.data) + 1, "name": name, "done": done}
        self.data.append(new_item)
        return new_item

app = Flask(__name__)

@app.route('/version', methods=['GET'])
def version():
    try:
        ser = SerialCommunicator()
        ser.open('/dev/ttyUSB0', 9600)
        response = ser.receive_line()
        if not response:
            return "504", 504
        ser.close()
        return response, 200
    except Exception as e:
        return str(e), 500

@app.route('/data', methods=['GET'])
def get_data():
    try:
        ser = SerialCommunicator()
        ser.open('/dev/ttyUSB0', 9600)
        data = ser.receive_line()
        if not data:
            return "504", 504
        ser.close()
        return jsonify(data.split('\n')), 200
    except Exception as e:
        return str(e), 500

@app.route('/data/<int:item_id>', methods=['GET'])
def get_item(item_id):
    try:
        ser = SerialCommunicator()
        ser.open('/dev/ttyUSB0', 9600)
        item = ser.receive_line()
