def log_access(tag_id):
    try:
        with open(ACCESS_LOG_FILE, 'a') as f:
            timestamp = datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')
            f.write(f'{timestamp} - RFID Tag: {tag_id}\n')
        logging.info(f'Access granted for RFID Tag: {tag_id}')
    except IOError as e:
        logging.error(f'Error writing to access log: {e}')

def monitor_rfid_reader():
    try:
        with serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT) as ser:
            while True:
                try:
                    tag_id = ser.readline().decode('utf-8').strip()
                    if tag_id:
                        log_access(tag_id)
                except serial.SerialException as e:
                    logging.error(f'Serial port error: {e}')
                except KeyboardInterrupt:
                    break

if __name__ == '__main__':
    monitor_thread = threading.Thread(target=monitor_rfid_reader)
    monitor_thread.start()

    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        monitor_thread.join()
        logging.info('RFID reader monitoring stopped.')

