import serial
import time
import sys

def read_pulse_oximeter():
    try:
        # Open serial port
        ser = serial.Serial('/dev/ttyUSB0', 9600, timeout=1)
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        sys.exit(1)

    try:
        while True:
            try:
                # Read data from serial port
                data = ser.readline().decode('utf-8').strip()
                if not data:
                    continue

                # Split data into heart rate and SpO2
                heart_rate, spo2 = data.split(',')
                heart_rate = int(heart_rate)
                spo2 = float(spo2)

                # Print the data
                print(f"Heart Rate: {heart_rate} bpm, SpO2: {spo2} %")

            except ValueError:
                print(f"Warning: Invalid data format: {data}")

            time.sleep(1)

    except KeyboardInterrupt:
        print("\nExiting...")

    finally:
        # Close the serial port
        ser.close()

if __name__ == "__main__":
    read_pulse_oximeter()

