        # Open serial port with specified settings
        with serial.Serial('/dev/serial0', 9600, timeout=1) as ser:
            while True:
                try:
                    # Read data from serial port with timeout
                    data = ser.readline(1).decode('utf-8').strip()
                    if not data:
                        continue  # Skip empty lines

                    # Parse the power value as a float
                    try:
                        power_value = float(data)
                    except ValueError:
                        logging.warning(f"Non-numeric data received: {data}")
                        continue  # Skip non-numeric data

                    # Log the power value
                    logging.warning(f"{datetime.now()} - Power: {power_value} W")

    except serial.SerialException as e:
        logging.error(f"Serial port error: {e}")
    except OSError as e:
        logging.error(f"OS error: {e}")
    except KeyboardInterrupt:
        logging.info("Exiting...")
    finally:
        # Ensure the serial port is closed
        if ser.is_open:
            ser.close()

if __name__ == "__main__":
    read_power_meter()

