import serial
import time
import sys

def send_command(command):
    try:
        # Establish serial connection
        ser = serial.Serial('/dev/rfcomm4', 38400, timeout=1)
        if not ser.is_open:
            raise RuntimeError("Failed to open serial port.")

        # Prefix command with 'X' and add newline
        command_to_send = 'X' + command + '\n'

        # Send command with delay
        ser.write(command_to_send.encode())
        time.sleep(0.1)

        # Read response (if any)
        response = ser.readline().decode().strip()
        if response:
            print(f"Received response: {response}")

        # Keep the connection open for subsequent commands
        return ser

    except RuntimeError as e:
        print(f"Error: {e}")
        sys.exit(1)
    finally:
        # Ensure the serial connection is closed
        if ser.is_open:
            ser.close()

def main():
    ser = send_command("")
    while True:
        try:
            command = input("Enter command (or 'exit' to quit): ")
            if command.lower() == 'exit':
                break
            send_command(command)
        except KeyboardInterrupt:
            print("\nExiting gracefully...")
            break

if __name__ == "__main__":
    main()
